export function FiverrHeaderPage() {
  const [hoveredCategory, setHoveredCategory] = useState<string | null>(null);
  // displayedCategory keeps content alive during the close animation
  const [displayedCategory, setDisplayedCategory] = useState<string | null>(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuCloseTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const menuDomTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wasOpenRef = useRef(false);
  const catNavRef = useRef<HTMLDivElement>(null);
  const triggerRectRef = useRef<DOMRect | null>(null);

  const openMenu = useCallback((cat: string, triggerEl?: HTMLElement) => {
    if (menuCloseTimer.current) clearTimeout(menuCloseTimer.current);
    if (triggerEl) triggerRectRef.current = triggerEl.getBoundingClientRect();
    setHoveredCategory(cat);
  }, []);

  const scheduleMenuClose = useCallback(() => {
    menuCloseTimer.current = setTimeout(() => setHoveredCategory(null), 500);
  }, []);

  // Drives the open/close transition and content lifecycle
  useEffect(() => {
    if (hoveredCategory) {
      if (menuDomTimer.current) clearTimeout(menuDomTimer.current);
      if (!wasOpenRef.current) {
        // Opening from closed: render with opacity:0 first, then flip open on next frame
        setDisplayedCategory(hoveredCategory);
        setIsMenuOpen(false);
        requestAnimationFrame(() => {
          setIsMenuOpen(true);
          wasOpenRef.current = true;
        });
      } else {
        // Switching categories: instant content swap, keep transition state untouched
        setDisplayedCategory(hoveredCategory);
      }
    } else {
      // Closing: trigger transition out, remove from DOM after it finishes
      setIsMenuOpen(false);
      wasOpenRef.current = false;
      menuDomTimer.current = setTimeout(() => setDisplayedCategory(null), 400);
    }
  }, [hoveredCategory]);

  const megaMenuStyle = (columnCount: number): React.CSSProperties => {
    if (!catNavRef.current) return {};
    const navRect = catNavRef.current.getBoundingClientRect();
    const isNarrow = columnCount <= 3;
    const base: React.CSSProperties = {
      position: 'fixed',
      top: navRect.bottom,
      zIndex: Z_POPOVER,
      backgroundColor: '#fff',
      borderRadius: 8,
      boxShadow: theme.boxShadows.z3,
      overflow: 'hidden',
    };
    if (isNarrow) {
      const fullWidth = Math.min(navRect.width, 1440);
      const narrowWidth = Math.round(fullWidth * 0.6);
      const triggerRect = triggerRectRef.current;
      // Align left edge to the trigger, but clamp so menu never overflows the screen
      const idealLeft = triggerRect ? triggerRect.left : navRect.left;
      const clampedLeft = Math.min(idealLeft, window.innerWidth - narrowWidth - 16);
      return { ...base, width: narrowWidth, left: Math.max(clampedLeft, 0) };
    }
    const maxWidth = 1440;
    const width = Math.min(navRect.width, maxWidth);
    const left = navRect.left + (navRect.width - width) / 2;
    return { ...base, left, width };
  };

  const activeMenu = displayedCategory ? CATEGORY_MENUS[displayedCategory] : null;

  const panelStyle: React.CSSProperties = isMenuOpen
    ? {
        opacity: 1,
        transform: 'translateY(0) scale(1)',
        pointerEvents: 'auto',
        transition: 'opacity 400ms cubic-bezier(.24,.48,0,.98), transform 400ms cubic-bezier(.24,.48,0,.98)',
      }
    : {
        opacity: 0,
        transform: 'translateY(-8px) scale(0.98)',
        pointerEvents: 'none',
        transition: 'opacity 300ms cubic-bezier(.24,.48,0,.98), transform 300ms cubic-bezier(.24,.48,0,.98)',
      };

  return (
    <div style={{ backgroundColor: '#fff' }}>
      <FiverrHeader />

      {/* ── Divider between top bar and categories ── */}
      <Divider />

      {/* ── Category Navigation ── */}
      <div ref={catNavRef}>
        <Container maxWidth="1400px" marginX="auto" paddingX="6" paddingTop="2" paddingBottom="2">
          <Carousel scrollType="row" breakpoints={{ default: 1 }}>
            <Track autoSlidesWidth showCardsFade slidesGap="2">
              {CATEGORIES.map((cat) => (
                <Slide key={cat}>
                  <Button
                    size="sm"
                    variant="ghost"
                    onMouseEnter={CATEGORY_MENUS[cat] ? (e) => openMenu(cat, e.currentTarget as HTMLElement) : undefined}
                    onMouseLeave={CATEGORY_MENUS[cat] ? scheduleMenuClose : undefined}
                  >
                    <Text size="b_sm" fontWeight="bold">{cat}</Text>
                  </Button>
                </Slide>
              ))}
            </Track>
            <Arrows position="default" size="xs" />
          </Carousel>
        </Container>
      </div>

      {/* ── Mega-menu ── */}
      {activeMenu && catNavRef.current && (
        <div
          style={{ ...megaMenuStyle(activeMenu.columns.length), ...panelStyle }}
          onMouseEnter={() => hoveredCategory && openMenu(hoveredCategory, undefined)}
          onMouseLeave={scheduleMenuClose}
        >
          <style>{`
            .mega-menu-item {
              display: flex; align-items: center; gap: 6px;
              padding: 8px 8px; border-radius: 8px; cursor: pointer;
              text-decoration: none !important; color: #62646a;
              font-size: 14px; line-height: 22px; white-space: nowrap;
            }
            .mega-menu-item:hover { background-color: #F5F5F5; color: #222325; }
            .mega-menu-item--cta { color: #222325; font-weight: 600; }
            .mega-menu-item--cta:hover { background-color: #F5F5F5; }
          `}</style>

          {/* columns */}
          <div style={{
            display: 'grid',
            gridTemplateColumns: `repeat(${activeMenu.columns.length}, auto)`,
            padding: '20px 24px 0',
            borderBottom: activeMenu.footer ? '1px solid #e4e5e7' : 'none',
          }}>
            {activeMenu.columns.map((groups, colIdx) => (
              <div key={colIdx} style={{
                paddingRight: colIdx < activeMenu.columns.length - 1 ? 24 : 0,
                paddingBottom: 16,
              }}>
                {groups.map((group, gIdx) => (
                  <div key={group.title} style={{ marginBottom: gIdx < groups.length - 1 ? 20 : 0 }}>
                    <Text
                      size="b_md"
                      fontWeight="semibold"
                      style={{ display: 'block', padding: '8px 8px', marginBottom: 0 }}
                    >
                      {group.title}
                    </Text>
                    <div>
                      {group.items.map((item) => (
                        <a key={item.label} href="#" className={`mega-menu-item${item.cta ? ' mega-menu-item--cta' : ''}`}>
                          {item.label}
                          {item.badge && <NewBadge />}
                          {item.icon === 'wand' && <WandIcon size="sm" />}
                          {item.cta && <ExternalLinkIcon size="sm" />}
                        </a>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            ))}
          </div>

          {/* optional footer banner */}
          {activeMenu.footer && (
            <div style={{
              padding: '20px 32px',
              display: 'flex', justifyContent: 'space-between', alignItems: 'center',
            }}>
              <Stack direction="column" gap="0.5">
                <Text size="b_sm" fontWeight="semibold">{activeMenu.footer.title}</Text>
                <Text size="b_sm" color="bodySecondary">{activeMenu.footer.description}</Text>
              </Stack>
              <Button size="md" variant="outline">{activeMenu.footer.cta}</Button>
            </div>
          )}
        </div>
      )}

      <Divider />
    </div>
  );
}
